@push('scripts')<script>$(function(){const tb=$('#return-lines tbody'),issue=$('#issue-select'),lineUrl='{{ route('wms.issue-returns.issue-line-options') }}';window.erpInitSelect2(issue,{ajax:{url:'{{ route('wms.issue-returns.issue-options') }}',delay:250,data:p=>({q:p.term||'',page:p.page||1}),processResults:d=>d}});function initLine(s){window.erpInitSelect2(s,{ajax:{url:lineUrl,delay:250,data:p=>({q:p.term||'',issue_document_id:issue.val()}),processResults:d=>d}});}function activateLines(){tb.find('select,input').prop('disabled',false);$('#add-return-line').prop('disabled',false);tb.find('.js-issue-line').each(function(){initLine($(this));});}issue.on('select2:select',activateLines);@if($selectedIssue)activateLines();@endif $('#add-return-line').on('click',function(){let i=tb.find('tr').length;const r=$('<tr><td><select class="form-select js-issue-line" name="lines['+i+'][issue_line_id]" required><option value="">เลือกรายการ</option></select></td><td><input class="form-control text-end" type="number" name="lines['+i+'][quantity]" min="0.00000001" step="any" required></td><td><button type="button" class="btn btn-sm btn-app-danger js-remove" title="ลบรายการ"><i class="bx bx-trash"></i></button></td></tr>');tb.append(r);initLine(r.find('.js-issue-line'));});tb.on('click','.js-remove',function(){if(tb.find('tr').length>1)$(this).closest('tr').remove();});window.erpAjaxForm({form:'#return-form',url:$('#return-form').attr('action'),method:'POST',redirect:true});});</script>@endpush
